function cli_log(string $m){echo '['.date('H:i:s').'] '.$m."\n";}
function cli_run(string $cmd,&$code=null): string {cli_log('$ '.mask_url($cmd));$out=sh($cmd,$code);if(trim($out)!=='')echo mask_url($out)."\n";return $out;}
