async function renderProj(){try{projectList=(await api('proj.list')).projects;const v=$('#v-proj');v.innerHTML='<div class="card"><h3>مدیریت پروژه‌ها</h3><button class="btn pri" id="padd">+ پروژه جدید</button><button class="btn" id="pref">به‌روزرسانی</button><p class="hint">نگهبان PHP تا زمانی که پردازش آن زنده باشد، سرویس را بازیابی می‌کند. راه‌اندازی پس از بوت نیازمند systemd است. هم‌زمان دو نگهبان برای یک پروژه اجرا نکنید.</p></div>'+'<div class="view-tools"><input class="inp" id="project-filter" aria-label="فیلتر پروژه" placeholder="جستجوی نام، ریپو یا وضعیت پروژه…"><select class="mini" id="project-preset"><option value="scraper4">Scraper4 + Deployer</option><option value="node">Node.js</option><option value="static">Static</option></select><button class="btn" id="preset-new">ساخت از الگو</button></div>'+projectList.map(p=>`<div class="card project-card"><h3>${esc(p.name)} <span class="tag ${p.service?.status==='running'?'ok':''}">${esc(p.service?.status||'stopped')}</span></h3><p class="hint ltr">${esc(p.repo_url)} · ${esc(p.branch)}${p.subfolder?' / '+esc(p.subfolder):''}<br>${esc(p.deploy_path)} · Port ${esc(p.port)}<br>${p.last_deploy?esc(p.last_deploy.commit)+' · '+fmtDate(p.last_deploy.time)+' · '+esc(p.last_deploy.status):''}</p><div class="row"><button class="btn pri sm" data-deploy="${p.id}">نصب / به‌روزرسانی</button>${p.start_cmd?`<button class="btn sm" data-start="${p.id}">اجرا</button><button class="btn danger sm" data-stop="${p.id}">توقف</button><button class="btn sm" data-restart="${p.id}">راه‌اندازی مجدد</button>`:''}${p.service?`<button class="btn sm" data-log="${esc(p.service.job)}">لاگ</button>`:''}<button class="btn sm" data-check="${p.id}">بررسی نصب</button><button class="btn sm" data-export="${p.id}">خروجی JSON</button><button class="btn sm" data-edit="${p.id}">تنظیمات</button><button class="btn sm" data-files="${p.id}">فایل‌ها</button><button class="btn danger sm" data-del="${p.id}">حذف پروفایل</button></div></div>`).join('');$('#padd').onclick=()=>projectDlg(null);$('#preset-new').onclick=()=>projectDlg(presetProject($('#project-preset').value));$('#project-filter').oninput=e=>v.querySelectorAll('.project-card').forEach(c=>c.classList.toggle('hide',!c.textContent.toLowerCase().includes(e.target.value.trim().toLowerCase())));actions(v,'data-check',projectPreflight);actions(v,'data-export',id=>projectExport(projectList.find(p=>p.id===id)));$('#pref').onclick=renderProj;actions(v,'data-deploy',async id=>{if(!await confirmDlg('فایل‌های پروژه به‌روزرسانی شوند؟ از داده‌ها بکاپ داشته باشید.'))return;const d=await api('proj.deploy',{id});openJob(d.job,'دیپلوی پروژه')});for(const action of ['start','stop','restart'])actions(v,'data-'+action,async id=>{const d=await api('proj.service',{id,action});renderProj();if(d?.job)openJob(d.job,'سرویس')});actions(v,'data-log',id=>openJob(id,'لاگ سرویس'));actions(v,'data-edit',id=>projectDlg(projectList.find(p=>p.id===id)));actions(v,'data-files',id=>{switchTab('files');navFm(projectList.find(p=>p.id===id).deploy_path)});actions(v,'data-del',async id=>{if(await confirmDlg('پروفایل حذف و سرویس آن متوقف شود؟ فایل‌ها باقی می‌مانند.')){await api('proj.delete',{id});renderProj()}})}catch(e){toast(e.message,'err')}}
// Import is data-only: it never saves, deploys, evaluates, or starts commands.
const PROJECT_JSON_MAX_BYTES=256*1024;
function parseProjectJson(text){
 if(new TextEncoder().encode(text).byteLength>PROJECT_JSON_MAX_BYTES)throw Error('JSON بزرگ‌تر از ۲۵۶ کیلوبایت است');
 let d;try{d=JSON.parse(text.replace(/^\uFEFF/,''))}catch(e){throw Error('JSON معتبر نیست؛ کوتیشن، ویرگول و براکت‌ها را بررسی کنید')}
 const record=v=>v!==null&&typeof v==='object'&&!Array.isArray(v);
 if(!record(d))throw Error('تنظیمات باید یک شیء JSON باشد، نه آرایه');
 if(Object.prototype.hasOwnProperty.call(d,'project')){if(Object.keys(d).length!==1||!record(d.project))throw Error('قالب project نامعتبر است');d=d.project}
 const strings=['name','type','repo_url','branch','subfolder','deploy_path','install_cmd','build_cmd','start_cmd','auth_token'];
 const allowed=new Set([...strings,'id','port','env','auto_start','is_daemon']);
 for(const k of Object.keys(d))if(!allowed.has(k))throw Error('فیلد ناشناخته: '+k);
 if(typeof d.name!=='string'||!d.name.trim()||typeof d.repo_url!=='string'||!d.repo_url.trim())throw Error('نام و repo_url الزامی هستند');
 const out=Object.create(null);
 for(const k of strings)if(Object.prototype.hasOwnProperty.call(d,k)){if(typeof d[k]!=='string'||/[\r\n\0]/.test(d[k]))throw Error('مقدار تک‌خطی متنی لازم است: '+k);out[k]=d[k]}
 if(out.type!==undefined&&!['node','python','php','static','other'].includes(out.type))throw Error('نوع پروژه نامعتبر است');
 if(!/^(https?:\/\/|git@|ssh:\/\/|file:\/\/|\/)/.test(out.repo_url))throw Error('آدرس ریپو نامعتبر است');
 if(out.deploy_path!==undefined&&out.deploy_path!==''&&(!out.deploy_path.startsWith('/')||out.deploy_path==='/'))throw Error('مسیر نصب باید مطلق و غیر از / باشد');
 if(out.branch?.startsWith('-')||/(^|\/)\.\.(\/|$)/.test(out.subfolder||''))throw Error('شاخه یا زیرپوشه نامعتبر است');
 if(Object.prototype.hasOwnProperty.call(d,'port')){if(!['string','number'].includes(typeof d.port))throw Error('پورت نامعتبر است');const v=String(d.port);if(v!==''&&(!/^\d+$/.test(v)||+v<1||+v>65535))throw Error('پورت باید بین ۱ و ۶۵۵۳۵ باشد');out.port=v}
 for(const k of ['auto_start','is_daemon'])if(Object.prototype.hasOwnProperty.call(d,k)){if(typeof d[k]!=='boolean')throw Error('مقدار '+k+' باید true یا false باشد');out[k]=d[k]}
 if(Object.prototype.hasOwnProperty.call(d,'env')){if(!record(d.env))throw Error('env باید یک شیء کلید/مقدار باشد');out.env=Object.create(null);for(const[k,v]of Object.entries(d.env)){if(!/^[a-zA-Z_][a-zA-Z0-9_]*$/.test(k)||!['string','number','boolean'].includes(typeof v)||(typeof v==='number'&&!Number.isFinite(v))||/[\r\n\0]/.test(String(v)))throw Error('متغیر محیطی نامعتبر: '+k);out.env[k]=String(v)}}
 // A portable profile cannot change the identity of the dialog being edited.
 return out;
}
function applyProjectJson(sh,d){
 for(const k of ['name','repo_url','branch','subfolder','deploy_path','port','install_cmd','build_cmd','start_cmd'])if(d[k]!==undefined)sh.querySelector('#jq-'+k).value=d[k];
 if(d.type!==undefined)sh.querySelector('#jq-type').value=d.type;
 if(d.auth_token!==undefined)sh.querySelector('#jq-token').value=d.auth_token;
 if(d.auto_start!==undefined)sh.querySelector('#jq-auto').checked=d.auto_start;
 if(d.is_daemon!==undefined)sh.querySelector('#jq-daemon').checked=d.is_daemon;
 if(d.env!==undefined){const box=sh.querySelector('#jq-env');const lines=box.value.split(/\r?\n/).filter(line=>{const i=line.indexOf('=');return i<0||!Object.prototype.hasOwnProperty.call(d.env,line.slice(0,i).trim())});box.value=[...lines.filter(line=>line.trim()!==''),...Object.entries(d.env).map(([k,v])=>k+'='+v)].join('\n')}
}

function parsedProjectVersion(value){const m=String(value||'').trim().match(/^v?(\d+)\.(\d+)(?:\.(\d+))?(?:-([0-9A-Za-z.-]+))?(?:\+[0-9A-Za-z.-]*)?$/);return m?{core:[m[1],m[2],m[3]||'0'].map(x=>BigInt(x)),pre:m[4]?.split('.')||[]}:null}
function compareProjectVersions(a,b){const x=parsedProjectVersion(a),y=parsedProjectVersion(b);if(!x||!y)return x?-1:y?1:0;for(let i=0;i<3;i++)if(x.core[i]!==y.core[i])return x.core[i]>y.core[i]?-1:1;if(!x.pre.length||!y.pre.length)return x.pre.length?1:y.pre.length?-1:0;for(let i=0;i<Math.max(x.pre.length,y.pre.length);i++){if(x.pre[i]===undefined)return 1;if(y.pre[i]===undefined)return -1;const a=x.pre[i],b=y.pre[i];if(a===b)continue;const an=/^\d+$/.test(a),bn=/^\d+$/.test(b);if(an&&bn){if(BigInt(a)===BigInt(b))continue;return BigInt(a)>BigInt(b)?-1:1}if(an!==bn)return an?1:-1;return a>b?-1:1}return 0}
function branchVersion(row,path='*'){const apps=(row.apps||[]).filter(a=>path==='*'||a.subfolder===path);return apps.map(a=>a.version).filter(v=>parsedProjectVersion(v)).sort(compareProjectVersions)[0]||''}
function sortedBranchRows(rows,path='*'){return [...rows].sort((a,b)=>compareProjectVersions(branchVersion(a,path),branchVersion(b,path))||a.name.localeCompare(b.name))}

function projectDlg(p){const fresh=!p;p=p||{id:'',name:'',type:'node',repo_url:'',branch:'main',subfolder:'',deploy_path:'',install_cmd:'',build_cmd:'',start_cmd:'',port:'',env:{},auto_start:false,is_daemon:true};const fields=[['name','نام پروژه'],['repo_url','آدرس ریپو'],['branch','شاخه'],['subfolder','زیرپوشه داخل ریپو'],['deploy_path','مسیر نصب روی سرور'],['port','پورت'],['install_cmd','دستور نصب'],['build_cmd','دستور بیلد'],['start_cmd','دستور اجرا']];const sh=openSheet(sheetHead('پروفایل پروژه')+`<div class="segtabs"><button class="btn" id="tab-gh">کاوشگر گیت‌هاب</button><button class="btn pri" id="tab-man">تنظیمات دستی</button><button class="btn" id="tab-json">ورود JSON</button></div><div id="json-exp" class="hide"><label class="lb">انتخاب فایل JSON تنظیمات (حداکثر ۲۵۶ کیلوبایت)</label><input class="inp" id="jq-json-file" type="file" accept=".json,application/json"><label class="lb">یا JSON را اینجا پیست کنید</label><textarea class="inp ltr" id="jq-json-text" rows="12" spellcheck="false" placeholder='{"name":"My project","repo_url":"https://github.com/owner/repo"}'></textarea><p class="hint">فقط فایل مورداعتماد وارد کنید؛ دستورات این پروفایل هنگام نصب قابل اجرا هستند. ورود JSON فقط فرم را پر می‌کند و چیزی را ذخیره یا اجرا نمی‌کند. متغیرهای محیطی موجود حفظ می‌شوند مگر همان کلید در JSON آمده باشد. شناسه id واردشده نادیده گرفته می‌شود.</p><button class="btn pri" id="jq-json-apply">اعمال در فرم برای بازبینی</button><p class="hint" id="jq-json-status" role="status" aria-live="polite"></p></div><div id="gh-exp" class="hide"><div class="row"><input class="inp ltr" id="gh-owner" value="fazilatma"><button class="btn pri" id="gh-load">دریافت مخازن</button></div><label class="lb">مخزن</label><select class="inp" id="gh-repo-sel"></select><label class="lb">مرتب‌سازی شاخه‌ها بر اساس نسخه پروژه</label><select class="inp" id="gh-version-path"><option value="*">بالاترین نسخه بین پروژه‌ها</option></select><p class="hint">جدیدترین نسخه ابتدا؛ نسخه‌های نامشخص در انتها. برای مقایسه یک پروژه مشخص، زیرپوشه آن را انتخاب کنید. بررسی نسخه‌های Node از package.json انجام می‌شود.</p><div class="row"><span class="hint" id="gh-branch-progress" role="status" aria-live="polite"></span><button class="btn sm" id="gh-branches-refresh">بررسی دوباره شاخه‌ها</button></div><div class="tblwrap" id="gh-branch-table"></div><label class="lb">شاخه انتخاب‌شده</label><select class="inp" id="gh-branch-sel"></select><div id="gh-apps-list"></div></div><div id="man-exp"><div class="grid2">${fields.map(([k,l])=>`<div><label class="lb">${l}</label><input class="inp ${k==='name'?'':'ltr'}" id="jq-${k}" value="${esc(p[k]||'')}"></div>`).join('')}<div><label class="lb">نوع</label><select class="inp" id="jq-type">${['node','python','php','static','other'].map(t=>`<option value="${t}" ${p.type===t?'selected':''}>${t}</option>`).join('')}</select></div><div><label class="lb">توکن ریپوی خصوصی؛ خالی بدون تغییر</label><input class="inp ltr" id="jq-token" type="password" placeholder="${p.has_token_hint?'ذخیره شده':''}"></div></div><label class="lb">متغیرهای محیطی؛ هر خط KEY=VALUE</label><textarea class="inp ltr" id="jq-env">${esc(Object.entries(p.env||{}).map(([k,v])=>k+'='+v).join('\n'))}</textarea><label class="lb"><input class="chk" id="jq-auto" type="checkbox" ${p.auto_start?'checked':''}> اجرای خودکار پس از دیپلوی</label><label class="lb"><input class="chk" id="jq-daemon" type="checkbox" ${p.is_daemon?'checked':''}> بازیابی خودکار سرویس هنگام خروج</label><button class="btn pri" id="jq-save">ذخیره پروفایل</button><p class="hint">ذخیره به‌تنهایی نصب را شروع نمی‌کند. پس از ذخیره دکمه نصب را بزنید.</p></div>`);
 const showTab=id=>{for(const tab of ['gh','man','json']){sh.querySelector('#'+tab+'-exp').classList.toggle('hide',tab!==id);sh.querySelector('#tab-'+tab).classList.toggle('pri',tab===id)}};
 const man=()=>showTab('man'),gh=()=>showTab('gh');sh.querySelector('#tab-man').onclick=man;sh.querySelector('#tab-gh').onclick=gh;sh.querySelector('#tab-json').onclick=()=>showTab('json');
 const jsonText=sh.querySelector('#jq-json-text'),jsonStatus=sh.querySelector('#jq-json-status');let jsonEpoch=0;
 jsonText.oninput=()=>{jsonEpoch++;jsonStatus.textContent=''};
